-- ct-kw85: the states a witness row with a sitting candidate names: 'from (the State of) X', 'State of X', "X's 2nd
-- District", 'District of X', 'District, X', a field that is the state, or '(D-XX)', '(XX-3)'. Its own step so the
-- regex join over the states runs once.
WITH states(name,code) AS (VALUES ('alabama','AL'),('alaska','AK'),('arizona','AZ'),('arkansas','AR'),('california','CA'),('colorado','CO'),('connecticut','CT'),('delaware','DE'),('florida','FL'),('georgia','GA'),('hawaii','HI'),('idaho','ID'),('illinois','IL'),('indiana','IN'),('iowa','IA'),('kansas','KS'),('kentucky','KY'),('louisiana','LA'),('maine','ME'),('maryland','MD'),('massachusetts','MA'),('michigan','MI'),('minnesota','MN'),('mississippi','MS'),('missouri','MO'),('montana','MT'),('nebraska','NE'),('nevada','NV'),('new hampshire','NH'),('new jersey','NJ'),('new mexico','NM'),('new york','NY'),('north carolina','NC'),('north dakota','ND'),('ohio','OH'),('oklahoma','OK'),('oregon','OR'),('pennsylvania','PA'),('rhode island','RI'),('south carolina','SC'),('south dakota','SD'),('tennessee','TN'),('texas','TX'),('utah','UT'),('vermont','VT'),('virginia','VA'),('washington','WA'),('west virginia','WV'),('wisconsin','WI'),('wyoming','WY'),('american samoa','AS'),('district of columbia','DC'),('guam','GU'),('northern mariana islands','MP'),('puerto rico','PR'),('virgin islands','VI'))
SELECT DISTINCT r.witness_key,s.code
FROM states s JOIN (SELECT f.id AS witness_key,f.full_text,f.raw_text
 FROM (SELECT DISTINCT witness_key FROM witness_member_candidates) c JOIN witness_member_facts f ON f.id=c.witness_key) r
 ON regexp_like(r.full_text,'\bfrom\s+(the\s+)?((state|commonwealth|territory)\s+of\s+)?'||s.name||'\b|\b(state|commonwealth|territory)\s+of\s+'||s.name||'\b|\b'||s.name||'(''s|’s)?,?\s+(\w+\s+){0,2}(congressional\s+)?district\b|\b(at[- ]large|\w+) (congressional )?district of '||s.name||'\b|\bdistrict[,;]?\s+'||s.name||'\b|(^|\|)\s*(of (the (state|commonwealth|territory) of )?)?'||s.name||'[\s.,;:]*($|\|)') OR regexp_like(r.raw_text,'\b[DRI]\s*[-–]\s*'||s.code||'\b|\('||s.code||'-(\d+|AL)\)')
